package com.nextrade.domain.ledger; import com.nextrade.common.enumtype.LedgerEntryType; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; public record Reservation(LedgerEntry entry) { public Reservation { if(entry.type()!=LedgerEntryType.RESERVATION) throw new IllegalArgumentException("Wrong ledger type"); } public static Reservation of(UserId user,Money amount,String reference){ return new Reservation(new LedgerEntry(LedgerEntryId.generate(),user,LedgerEntryType.RESERVATION,amount,reference,java.time.Instant.now())); } }